update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle en Essonne","mecanisme":"Un département qui empile trois industries sans rapport entre elles. Les plateformes e-commerce du nord, la mécanique de précision de la vallée de la Seine, les pilotes et les laboratoires du plateau de Saclay. Nos techniciens couvrent les trois et se déplacent sur vos sites : nous n''avons ni agence ni hub de techniciens en Essonne.","cta":"Faire chiffrer ma maintenance en Essonne","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option pour les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs, dont des automaticiens SIEMENS et Schneider et des roboticiens ABB et Fanuc"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, et des techniciens qui se déplacent partout en France"}]},{"type":"probleme","punchline":"Un trieur qui lâche à Chilly-Mazarin en fin d''après-midi, ce sont des commandes qui basculent au lendemain. Pendant ce temps, votre responsable maintenance cherche un prestataire disponible.","puces":[{"accroche":"Vos équipements n''ont rien en commun d''un site à l''autre.","texte":"Convoyeurs au nord, traitement thermique à Corbeil, banc d''essai aux Ulis : un prestataire mono-métier vous laisse nu sur le reste."},{"accroche":"Le préventif glisse depuis des mois.","texte":"Un poste vacant dans l''équipe, et le correctif absorbe tout le budget."},{"accroche":"Le recrutement francilien ne suit pas.","texte":"Les annonces de technicien de maintenance restent ouvertes, les contre-offres s''enchaînent, la production attend."},{"accroche":"Les sites du sud du département sont loin de tout.","texte":"D''Étampes à la Ferté-Alais, les parcs vieillissent sans équipe dédiée."},{"accroche":"La panne du soir n''a personne en face.","texte":"Sans astreinte écrite, l''urgence se règle par une chaîne d''appels sans garantie."}]},{"type":"offre","lignes":[{"prestation":"**Équipements logistiques du nord du département** : convoyeurs, trieurs, quais, systèmes automatisés de manutention. Voir la [maintenance des sites logistiques](/secteurs/logistique/).","benefice":"La vague de préparation repart, et la vente en ligne ne se décale pas d''une journée."},{"prestation":"**Mécanique de précision et traitement thermique** de la vallée de la Seine : roulements, réducteurs, alignements, équilibrage.","benefice":"La cote est tenue, et vos rebuts arrêtent de grimper après chaque intervention."},{"prestation":"**Pilotes, bancs et équipements de laboratoire** du plateau de Saclay et des Ulis : documentation stricte, traçabilité complète.","benefice":"Vos essais restent recevables, parce que chaque geste est écrit."},{"prestation":"**Électricité industrielle et automatisme** : armoires, variateurs, automates SIEMENS et Schneider, en [maintenance électrique](/expertises/electrique/) comme en [automatisme](/expertises/automatisme/).","benefice":"Un seul interlocuteur du moteur au programme, sans renvoi de responsabilité."},{"prestation":"**Préventif reconstruit sur l''usage réel** de chaque équipement, pas sur un calendrier hérité.","benefice":"Le correctif recule, le budget redevient prévisible poste par poste."},{"prestation":"**Technicien intégré sur site** en [sous-traitance maintenance](/offres/residence/), prise de poste en 2 à 3 semaines.","benefice":"Le poste vacant est tenu pendant que votre recrutement continue, remplacement assuré en cas d''absence."},{"prestation":"**Astreinte 24/24 et 7/7 en option**, cadre d''appel écrit au contrat.","benefice":"La panne de 22 heures a un numéro et un technicien en face, pas un répondeur."}],"prose":[{"texte":"Un déménagement de ligne ou un transfert entre deux sites du département se prépare à J-90. Notre offre [déménagement de machines](/offres/chantier/demenagement-machines/) couvre le démontage, le levage, le remontage et la requalification."}]},{"type":"deroule","etapes":[{"titre":"Votre demande","texte":"par téléphone au 04 78 33 72 05 ou par le formulaire. Rappel dans l''heure aux horaires ouvrés, c''est le seul délai que nous signons."},{"titre":"La qualification à distance","texte":"équipement, symptômes, niveau d''urgence, habilitations requises, pièces probables. Cette étape évite le mauvais profil et le second déplacement."},{"titre":"Le chiffrage","texte":"périmètre, moyens, conditions d''accès, temps d''arrêt prévu. Tout s''écrit avant le départ du technicien."},{"titre":"L''intervention","texte":"consignation, diagnostic, réparation, essais, remise en service avec votre équipe."},{"titre":"Le compte rendu","texte":"causes, actions, mesures, préconisations, versés dans votre GMAO. Vos données restent chez vous."},{"titre":"La décision suivante","texte":"réparation durable, remplacement, ou entrée dans un plan préventif. Vous choisissez sur des faits écrits."}]},{"type":"garanties","puces":[{"accroche":"Un seul chargé d''affaires pour tous vos sites du 91","texte":"il connaît vos accès, vos consignes d''accueil sécurité et vos contraintes de coactivité. Vous n''expliquez pas votre usine à chaque appel."},{"accroche":"Des habilitations vérifiées avant l''arrivée","texte":"électriques, travail en hauteur, environnements spécifiques. Le plan de prévention est signé avant le premier jour, jamais pendant."},{"accroche":"Une couverture qui ne dépend pas d''une seule personne","texte":"congés, absence, départ, un profil équivalent reprend la mission, briefé sur vos machines. La continuité est écrite au contrat."}]},{"type":"cta","question":"Besoin de couvrir un poste maintenance vacant pendant que votre recrutement avance ?","bouton":"Faire chiffrer ma maintenance en Essonne","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Un technicien affecté en continu sur un site proche de Paris","texte":", en renfort d''une équipe de maintenance sous forte activité, sur les lignes de production","lienLibelle":"Étude de cas FDJ : site proche de Paris","lienHref":"/preuves/fdj/"},{"titre":"Un électromécanicien habilité risque chimique niveau 1, mobilisé 6 mois","texte":"pour la remise en état d''un site de traitement des eaux industrielles","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"La construction complète d''un site industriel de recherche et développement près de Paris","texte":"pilotage de chantier, coordination des métiers, jalons tenus","lienLibelle":"Étude de cas ORTHUS x ECOCEM : nouveau site","lienHref":"/preuves/orthus-ecocem/"},{"titre":"Préventif tenu sur un centre logistique exploité en continu","texte":", par créneaux de 8 heures, une semaine sur deux, depuis septembre 2022","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"},{"titre":"Deux techniciens dédiés au curatif des convoyeurs, trieurs et systèmes de packaging","texte":"présence permanente sur site","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous dans tout le département ?","reponse":"Oui : de Massy et Chilly-Mazarin au nord, jusqu''à Étampes et la Ferté-Alais au sud, en passant par Corbeil-Essonnes, Évry-Courcouronnes, Les Ulis, Fleury-Mérogis et Viry-Châtillon. Disons-le franchement : nous n''avons ni agence ni hub de techniciens en Essonne. Un chargé d''affaires qualifie la demande, la mission est préparée avant l''arrivée, et l''exécution se fait sur votre site."},{"question":"Faites-vous le CVC, le SSI ou la maintenance de bâtiments ?","reponse":"Non. Le confort thermique, le froid de bâtiment et la sécurité incendie relèvent d''autres corps de métier. Notre terrain, c''est l''outil de production : machines, lignes, utilités industrielles. Cette spécialisation est ce qui rend nos techniciens réellement utiles sur vos équipements."},{"question":"Nous avons déjà un prestataire, comment tester Migen sans tout casser ?","reponse":"Par un dépannage isolé ou un périmètre d''essai limité à quelques équipements. Vous jugez sur le compte rendu, la tenue des dates et le comportement sur site. La bascule complète se décide après, sur des faits."},{"question":"Pouvez-vous travailler dans notre GMAO ?","reponse":"Oui. Nos comptes rendus s''y saisissent directement : historique par machine, temps passé, pièces, préconisations. Rien à ressaisir ailleurs."},{"question":"Quels délais d''intervention constatez-vous en Essonne ?","reponse":"Aucun délai chiffré n''est promis : chaque déplacement dépend du défaut, des habilitations et des pièces. Deux engagements tenus à la place. Le rappel dans l''heure aux horaires ouvrés, et l''astreinte 24/24 et 7/7 en option pour les sites qui ne peuvent pas attendre le matin."},{"question":"Combien coûte un contrat de maintenance préventive ?","reponse":"Notre [contrat Zéro arrêt](/offres/zero-arret/) est chiffré sur devis, engagement type 6 mois renouvelable, avec trois niveaux de couverture. Le périmètre s''écrit machine par machine après un état des lieux, et le diagnostic de départ est gratuit."}]},{"type":"ctaFinal","question":"Besoin d''un plan préventif qui tienne malgré les effectifs du moment ?","bouton":"Faire chiffrer ma maintenance en Essonne","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/paris/essonne/';
